// CPTS arsenal page (generated by scripts/build-cpts.mjs). Adds copy buttons to
// the command blocks, a search over the tools (by port, service, tag or name),
// and the Cyber Kill Chain rail: click a stage to narrow to it, and the rail
// marks the stage you're reading. Without scripts the page is the whole
// reference, every tool expandable, every stage anchored.
import { initCommandPalette } from "../js/command-palette.js?v=search2";
import { initSiteHeader } from "../js/site-header.js?v=276fa973-header";
import { initTheme } from "../js/theme.js?v=276fa973";
import { copyTextToClipboard } from "../js/markdown.js?v=276fa973-th";
import { highlightAllIn } from "../js/highlight.js?v=276fa973";
import { initHeroDither } from "../js/hero-dither.js?v=276fa973-idle";

const COPY_ICON = '<svg class="writeup-code-copy-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M6 15H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v1"/></svg>';

// Highlight every command block and wrap it in the site's code-block shell
// (panel, language label, copy button, line-number gutter), the same markup
// the writeups use. Done here rather than with enhanceMarkdownBody because that
// also rewrites heading ids, which would collide with the build-time ones and
// break the stage headings' aria-labelledby.
const enhanceCode = () => {
  const bodies = document.querySelectorAll(".cpts-tool-body");
  for (const body of bodies) highlightAllIn(body);
  for (const pre of document.querySelectorAll(".cpts-tool-body pre")) {
    if (pre.closest(".writeup-code-block")) continue;
    const wrapper = document.createElement("div");
    wrapper.className = "writeup-code-block";
    pre.parentNode.insertBefore(wrapper, pre);

    const langSpan = pre.querySelector(".bt-code-lang");
    const language = langSpan?.textContent?.trim() || "";
    langSpan?.remove();

    const header = document.createElement("div");
    header.className = "writeup-code-header";
    const langLabel = document.createElement("span");
    langLabel.className = "writeup-code-lang";
    langLabel.textContent = language;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "writeup-code-copy";
    btn.innerHTML = COPY_ICON;
    const btnLabel = document.createElement("span");
    btnLabel.className = "writeup-code-copy-label";
    btnLabel.textContent = "Copy";
    btn.append(btnLabel);
    btn.addEventListener("click", () => {
      const code = pre.querySelector("code")?.textContent || pre.textContent || "";
      void copyTextToClipboard(code.trim(), btnLabel, "Copy");
    });
    header.append(langLabel, btn);

    const main = document.createElement("div");
    main.className = "writeup-code-main";
    const code = pre.querySelector("code");
    const lines = (code?.textContent ?? pre.textContent ?? "").replace(/\n$/, "").split("\n").length;
    if (lines >= 2) {
      main.classList.add("has-line-numbers");
      const gutter = document.createElement("span");
      gutter.className = "writeup-code-gutter";
      gutter.setAttribute("aria-hidden", "true");
      gutter.textContent = Array.from({ length: lines }, (_, i) => i + 1).join("\n");
      main.append(gutter);
    }
    main.append(pre);
    wrapper.append(header, main);
  }
};

// Target bar: swap the reader's own TARGET / ATTACKER_IP / DOMAIN into every
// command. The notes write those tokens literally, so without JS they read as
// plain placeholders; here each token is wrapped in a span whose text follows
// the matching input. Values are a per-viewer convenience, saved in
// localStorage and guarded. Copy reads the span text, so it copies the real
// command. Tokens are tokenised after highlighting, inside code only.
const VARS_KEY = "cpts-vars";
const HOST_KEY = "cpts-host";
const VAR_TOKEN = { target: "TARGET", ip: "ATTACKER_IP", domain: "DOMAIN" };
const TOKEN_VAR = { TARGET: "target", ATTACKER_IP: "ip", DOMAIN: "domain" };
// HOST is a slot that works with either the target IP or the domain; the reader
// flips it per tool. The fixed tokens map straight to one input. Match a whole
// token not glued to a word char or a dot, so TARGET.com and the like are left
// alone.
const TOKEN_RE = /(?<![\w.])(TARGET|ATTACKER_IP|DOMAIN|HOST)(?![\w.])/g;

// Shared across the target bar: the reader's current values and, per tool slug,
// which value each HOST slot resolves to ("target" | "domain").
let currentVars = {};
let hostChoice = {};

const loadJSON = (key) => {
  try { return JSON.parse(localStorage.getItem(key)) || {}; } catch { return {}; }
};
const saveJSON = (key, value) => {
  try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* ignore */ }
};

const tokeniseVars = () => {
  const codes = document.querySelectorAll(".cpts-tool-body code");
  for (const code of codes) {
    const slug = code.closest(".cpts-tool")?.id.replace(/^tool-/, "") || "";
    const walker = document.createTreeWalker(code, NodeFilter.SHOW_TEXT);
    const nodes = [];
    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
      if (!n.parentElement.closest(".cpts-var") && TOKEN_RE.test(n.nodeValue)) nodes.push(n);
    }
    for (const node of nodes) {
      const frag = document.createDocumentFragment();
      let last = 0;
      node.nodeValue.replace(TOKEN_RE, (token, _g, offset) => {
        if (offset > last) frag.append(node.nodeValue.slice(last, offset));
        const span = document.createElement("span");
        if (token === "HOST") {
          // A switchable slot: plain text in the command, so it selects and
          // copies like any other word. The IP / domain switch for it lives in
          // the code block's header, beside Copy.
          span.className = "cpts-var cpts-host";
          span.dataset.token = "HOST";
          span.dataset.tool = slug;
        } else {
          span.className = "cpts-var";
          span.dataset.var = TOKEN_VAR[token];
          span.dataset.token = token;
        }
        span.textContent = token;
        frag.append(span);
        last = offset + token.length;
        return token;
      });
      if (last < node.nodeValue.length) frag.append(node.nodeValue.slice(last));
      node.parentNode.replaceChild(frag, node);
    }
  }
};

const applyVars = () => {
  for (const span of document.querySelectorAll(".cpts-var")) {
    let varName = span.dataset.var;
    let token = span.dataset.token;
    if (token === "HOST") {
      const choice = hostChoice[span.dataset.tool] === "domain" ? "domain" : "target";
      varName = choice;
      token = VAR_TOKEN[choice];
      span.dataset.choice = choice;
    }
    const value = (currentVars[varName] || "").trim();
    span.textContent = value || token;
    span.classList.toggle("is-set", Boolean(value));
  }
  for (const button of document.querySelectorAll(".cpts-host-opt")) {
    const choice = hostChoice[button.dataset.tool] === "domain" ? "domain" : "target";
    button.setAttribute("aria-pressed", button.dataset.choice === choice ? "true" : "false");
  }
};

const setHost = (slug, choice) => {
  hostChoice[slug] = choice;
  saveJSON(HOST_KEY, hostChoice);
  applyVars();
};

// Every code block with a HOST slot gets an IP / Domain switch in its header,
// next to Copy. The choice is per tool, so all of a tool's blocks follow it.
const addHostSwitches = () => {
  for (const block of document.querySelectorAll(".writeup-code-block")) {
    const host = block.querySelector(".cpts-host");
    const copy = block.querySelector(".writeup-code-copy");
    if (!host || !copy) continue;
    const slug = host.dataset.tool;
    const group = document.createElement("div");
    group.className = "cpts-host-switch";
    group.setAttribute("role", "group");
    group.setAttribute("aria-label", "Use the target IP or the domain for HOST");
    for (const [choice, label] of [["target", "IP"], ["domain", "Domain"]]) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "cpts-host-opt";
      button.dataset.tool = slug;
      button.dataset.choice = choice;
      button.textContent = label;
      button.setAttribute("aria-pressed", "false");
      button.addEventListener("click", () => setHost(slug, choice));
      group.append(button);
    }
    const actions = document.createElement("div");
    actions.className = "cpts-code-actions";
    copy.replaceWith(actions);
    actions.append(group, copy);
  }
};

const initTargets = () => {
  const inputs = [...document.querySelectorAll(".cpts-target-input")];
  const clearBtn = document.getElementById("cpts-targets-clear");
  if (!inputs.length) return;
  tokeniseVars();
  addHostSwitches();
  currentVars = loadJSON(VARS_KEY);
  hostChoice = loadJSON(HOST_KEY);
  for (const input of inputs) input.value = currentVars[input.dataset.var] || "";
  const hasAny = () => inputs.some((i) => i.value.trim());
  const refresh = () => {
    const next = {};
    for (const input of inputs) { const v = input.value.trim(); if (v) next[input.dataset.var] = v; }
    currentVars = next;
    saveJSON(VARS_KEY, next);
    applyVars();
    if (clearBtn) clearBtn.hidden = !hasAny();
  };
  for (const input of inputs) input.addEventListener("input", refresh);
  if (clearBtn) clearBtn.addEventListener("click", () => {
    for (const input of inputs) input.value = "";
    refresh();
  });
  applyVars();
  if (clearBtn) clearBtn.hidden = !hasAny();
};

// Open-ports filter state, shared with the arsenal's paint so the two filters
// (search text and open ports) narrow the grid together.
const PORTS_KEY = "cpts-ports";
let openPorts = new Set();
let repaintArsenal = () => {};

const initPorts = () => {
  const panel = document.getElementById("cpts-ports");
  if (!panel) return;
  const buttons = [...panel.querySelectorAll(".cpts-port")];
  const clearBtn = document.getElementById("cpts-ports-clear");
  const countEl = panel.querySelector("[data-ports-count]");
  let saved;
  try { saved = JSON.parse(localStorage.getItem(PORTS_KEY)) || []; } catch { saved = []; }
  openPorts = new Set((Array.isArray(saved) ? saved : []).map(String));

  const sync = () => {
    for (const button of buttons) {
      const on = openPorts.has(button.dataset.port);
      button.classList.toggle("is-open", on);
      button.setAttribute("aria-pressed", on ? "true" : "false");
    }
    if (clearBtn) clearBtn.hidden = openPorts.size === 0;
    if (countEl) countEl.textContent = openPorts.size ? `${openPorts.size} open` : "";
    saveJSON(PORTS_KEY, [...openPorts]);
    repaintArsenal();
  };

  for (const button of buttons) button.addEventListener("click", () => {
    const port = button.dataset.port;
    if (openPorts.has(port)) openPorts.delete(port); else openPorts.add(port);
    sync();
  });
  if (clearBtn) clearBtn.addEventListener("click", () => { openPorts.clear(); sync(); });
  sync();
};

// Stage checklists: remember each tick per viewer and keep the done/total
// count. localStorage is a per-viewer convenience, so every access is guarded
// and the page works the same if it is unavailable.
const CHECK_KEY = "cpts-checklist";
const loadChecks = () => {
  try { return JSON.parse(localStorage.getItem(CHECK_KEY)) || {}; } catch { return {}; }
};
const saveChecks = (state) => {
  try { localStorage.setItem(CHECK_KEY, JSON.stringify(state)); } catch { /* ignore */ }
};

const initChecklists = () => {
  const panels = [...document.querySelectorAll(".cpts-checklist")];
  if (!panels.length) return;
  const state = loadChecks();
  for (const panel of panels) {
    const stage = panel.dataset.stage;
    const boxes = [...panel.querySelectorAll('input[type="checkbox"]')];
    const countEl = panel.querySelector("[data-check-count]");
    const saved = state[stage] || {};
    for (const box of boxes) if (saved[box.dataset.idx]) box.checked = true;

    const update = () => {
      const done = boxes.filter((b) => b.checked).length;
      if (countEl) countEl.textContent = `${done}/${boxes.length}`;
      panel.classList.toggle("is-complete", done === boxes.length);
    };

    for (const box of boxes) {
      box.addEventListener("change", () => {
        const current = loadChecks();
        const forStage = current[stage] || {};
        if (box.checked) forStage[box.dataset.idx] = true;
        else delete forStage[box.dataset.idx];
        if (Object.keys(forStage).length) current[stage] = forStage;
        else delete current[stage];
        saveChecks(current);
        update();
      });
    }
    update();
  }
};

// One guide open at a time: opening a tool closes whichever was open, so the
// page never stacks two long cards. A second click on an open card minimises
// it (native <details> behaviour), leaving the grid collapsed.
const initAccordion = () => {
  const guides = [...document.querySelectorAll(".cpts-tool > details")];
  for (const guide of guides) {
    guide.addEventListener("toggle", () => {
      if (!guide.open) return;
      for (const other of guides) if (other !== guide && other.open) other.open = false;
      // the cards above it just collapsed, so keep this one's head in view
      guide.querySelector("summary")?.scrollIntoView({ block: "nearest" });
    });
  }
};

const initArsenal = () => {
  const input = document.getElementById("cpts-q");
  const countLabel = document.getElementById("cpts-count");
  const emptyNote = document.getElementById("cpts-empty");
  const stages = [...document.querySelectorAll(".cpts-stage")];
  const tools = [...document.querySelectorAll(".cpts-tool")];
  const railLinks = [...document.querySelectorAll(".cpts-rail-stage")];
  if (!stages.length) return;
  const total = tools.length;
  let stageFilter = "";
  // Each tool lives inside exactly one stage section, so counts come from the DOM.
  const toolsIn = (stage) => [...stage.querySelectorAll(".cpts-tool")];

  const paint = () => {
    const query = (input?.value || "").trim().toLowerCase();
    const words = query.split(/\s+/).filter(Boolean);
    for (const tool of tools) {
      const text = tool.dataset.search || "";
      const searchOk = words.every((word) => text.includes(word));
      // Port gate: a tool with no panel port is core and always passes; one with
      // ports passes only when a marked-open port is among them.
      const toolPorts = (tool.dataset.ports || "").split(" ").filter(Boolean);
      const portOk = openPorts.size === 0 || toolPorts.length === 0 || toolPorts.some((p) => openPorts.has(p));
      tool.hidden = !(searchOk && portOk);
    }
    let shown = 0;
    for (const stage of stages) {
      const visibleIn = toolsIn(stage).filter((tool) => !tool.hidden).length;
      stage.hidden = (stageFilter && stage.dataset.stage !== stageFilter) || visibleIn === 0;
      if (!stage.hidden) shown += visibleIn;
    }
    for (const link of railLinks) {
      const id = link.dataset.stage;
      const badge = link.querySelector(".cpts-rail-count");
      if (badge) {
        const section = id ? stages.find((stage) => stage.dataset.stage === id) : null;
        badge.textContent = String(section ? toolsIn(section).filter((tool) => !tool.hidden).length : tools.filter((tool) => !tool.hidden).length);
      }
      link.classList.toggle("is-active", id === stageFilter);
    }
    if (countLabel) countLabel.textContent = query || stageFilter || openPorts.size ? `${shown} of ${total} tools` : `${total} tools`;
    if (emptyNote) emptyNote.hidden = shown > 0;
  };

  // The ports filter re-runs this same paint, so both filters stay in step.
  repaintArsenal = paint;
  input?.addEventListener("input", paint);

  for (const link of railLinks) {
    link.addEventListener("click", () => {
      // "All stages" (empty data-stage) clears; clicking the active stage clears too.
      const id = link.dataset.stage;
      stageFilter = id && id !== stageFilter ? id : "";
      paint();
      // let the anchor jump happen after the filter resolves which sections exist
      window.requestAnimationFrame(() => {
        const target = stageFilter ? document.getElementById(`stage-${stageFilter}`) : document.getElementById("cpts-main");
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });
  }

  // While browsing (no stage filter), mark the stage currently in view.
  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver((entries) => {
      if (stageFilter) return;
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const id = entry.target.dataset.stage;
        for (const link of railLinks) link.classList.toggle("is-active", link.dataset.stage === id);
      }
    }, { rootMargin: "-20% 0px -70% 0px" });
    for (const stage of stages) observer.observe(stage);
  }

  paint();
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initHeroDither();
  enhanceCode();
  initTargets();
  initChecklists();
  initAccordion();
  initArsenal();
  initPorts();
});
